<template>
  <div class="sales-shopping" data-sales-shopping>
    <PageHead title="销售选购" desc="选商品、配件和服务，核对后生成交付清单。">
      <el-button v-if="store.can('product:benefit:read')" @click="recordsOpen=true">销售记录</el-button>
      <el-dropdown trigger="click"><el-button aria-label="销售选购更多操作">更多</el-button><template #dropdown><el-dropdown-menu>
        <el-dropdown-item @click="newSession">开始新方案</el-dropdown-item>
        <el-dropdown-item v-if="store.can('product:benefit:read')" @click="commonOpen=true">常用组合</el-dropdown-item>
        <el-dropdown-item v-if="store.can('product:sales-config:read')" @click="router.push('/sales-configurations')">管理选配方案</el-dropdown-item>
      </el-dropdown-menu></template></el-dropdown>
    </PageHead>
    <div class="sales-status" role="status"><span :data-sales-save-state="saveState">{{saveLabel}}</span><span v-if="draft.id">{{draft.name}}</span><el-button v-if="error" link type="danger" @click="retry">重试保存</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="sales-notice"/>
    <el-alert v-if="!supported" title="此方案版本暂不支持在销售选购中修改，原内容已保留。" type="warning" :closable="false"/>
    <template v-if="supported && !missing">
      <div class="sales-tools panel">
        <el-input v-model="keyword" clearable placeholder="搜索商品、规格或编号" aria-label="搜索销售商品" data-sales-search/>
        <el-popover trigger="click" placement="bottom-start" :width="300"><template #reference><el-button :class="{'is-active':categoryIds.length}" data-sales-category-trigger :title="categoryCaption.title">{{categoryCaption.label}}</el-button></template><CategoryFilterTree :categories="store.data.categories" :selected-ids="categoryIds" :state-key="`sales-shopping:${store.activeUserId}:${store.previewUserId}`" @toggle="toggleCategory" @clear="categoryIds=[]"/></el-popover>
        <el-select v-model="brand" filterable clearable placeholder="品牌" aria-label="销售商品品牌" data-sales-brand><el-option v-for="value in brands" :key="value" :label="value" :value="value"/></el-select>
        <el-button v-if="keyword||brand||categoryIds.length" link @click="keyword='';brand='';categoryIds=[]">清除筛选</el-button>
        <span class="muted" data-sales-result-count>{{families.length}} 款商品</span>
      </div>
      <div class="sales-context panel" data-sales-device>
        <div><small>本次使用设备</small><strong>{{deviceLabel}}</strong></div>
        <el-button @click="deviceOpen=true">{{draft.device?'更换设备':'选择已有设备'}}</el-button>
        <el-button v-if="draft.device" link @click="chooseDevice(null)">清除设备</el-button>
        <span v-if="draft.device && !draft.includedPhoneSkuId" class="muted">仅用于核对适用性，未加入手机实物</span>
      </div>
      <div class="sales-grid">
        <section class="panel sales-catalog" aria-label="销售商品">
          <h2>商品</h2><p v-if="!families.length" class="muted">没有符合筛选的在售商品。</p>
          <button v-for="family in shownFamilies" :key="family.id" class="family-card" :class="{selected:family.id===selectedFamilyId}" :data-sales-family="family.id" :aria-pressed="family.id===selectedFamilyId" @click="openFamily(family.id)">
            <strong>{{family.name}}</strong><span>{{familyBrandText(store.data,family)||categoryPath(store.data,family.categoryId)}}</span><small>{{familySkus(family.id).length}} 个可选规格</small>
          </button>
          <el-button v-if="families.length>shownCount" link @click="shownCount+=24">继续查看 {{Math.min(24,families.length-shownCount)}} 款</el-button>
        </section>
        <section class="panel sales-options" aria-label="规格与相关选配">
          <template v-if="selectedFamily">
            <div class="section-head"><h2>{{selectedFamily.name}}</h2><span class="muted">选择实际规格</span></div>
            <div class="sku-options"><button v-for="sku in familySkus(selectedFamily.id)" :key="sku.id" :data-sales-sku="sku.id" :class="{selected:sourceSkuId===sku.id}" :aria-pressed="sourceSkuId===sku.id" @click="browseSku(sku.id)"><strong>{{displaySpec(sku.id)||sku.skuName||sku.code}}</strong><small>{{savedSkuCode(sku)}}</small></button></div>
          </template>
          <template v-if="sourceSummary">
            <nav v-if="trail.length>1" class="source-trail" aria-label="最近查看的相关商品"><button v-for="(entry,index) in trail" :key="`${entry.skuId}:${entry.positionId||''}`" @click="returnToSource(index)">{{benefitSkuSummary(store.data,entry.skuId)?.name||'来源已失效'}}</button></nav>
            <div class="current-product" data-sales-current-source><div><small>正在查看</small><h3>{{sourceSummary.name}}</h3><p class="muted">{{displaySpec(sourceSummary.skuId,sourceSummary.spec)}}</p></div><el-button type="primary" :disabled="!canEdit||businessPending" :data-sales-add-current="sourceSkuId" @click="addCurrent">加入清单</el-button></div>
            <el-button v-if="sourceRole==='host' && (draft.device?.kind!=='sku'||draft.device.skuId!==sourceSkuId)" link type="primary" @click="chooseDevice({kind:'sku',skuId:sourceSkuId})">用作本次使用设备</el-button>
            <div class="section-head related-head"><h2>相关选配</h2><span v-if="candidates.resolution.plan" class="muted">{{candidates.resolution.plan.name}}</span></div>
            <el-alert v-if="['conflict','invalid'].includes(candidates.resolution.state)" :title="candidates.resolution.message" type="warning" :closable="false"/>
            <p v-if="!candidateGroups.length" class="muted">{{candidates.resolution.message||'此商品暂未配置相关选配，可继续浏览其他商品。'}}</p>
            <section v-for="group in candidateGroups" :key="group.key" class="option-group"><div class="section-head"><h3>{{group.name}}</h3><small>{{group.required?'必选':'可选'}}</small></div>
              <article v-for="candidate in group.rows" :key="candidate.key" class="candidate-card" :data-sales-candidate="candidate.key" :data-sales-candidate-sku="candidate.skuId||''">
                <div class="candidate-main"><strong>{{candidate.summary?.name||candidate.item.name}}</strong><p class="muted">{{candidate.summary?displaySpec(candidate.summary.skuId,candidate.summary.spec):candidate.item.service?.description}}</p><div class="candidate-state"><el-tag size="small" :type="statusType(candidate.status)">{{statusLabel(candidate)}}</el-tag><span>{{targetLabel(candidate)}}</span></div>
                  <details v-if="candidate.reason||candidate.item.note||candidate.item.source"><summary>查看适用依据</summary><p>{{candidate.reason||'不要求适用核验，作为搭配选择。'}}</p><p v-if="candidate.item.note">{{candidate.item.note}}</p><p v-if="candidate.item.source" class="muted">{{candidate.item.source}}</p></details>
                </div><div class="candidate-actions"><el-button type="primary" size="small" :disabled="!candidate.canAdd||!canEdit||businessPending" :data-sales-add-candidate="candidate.key" @click="addCandidate(candidate)">加入</el-button><el-button v-if="candidate.skuId" link size="small" @click="browseSku(candidate.skuId!)">查看相关</el-button></div>
              </article>
            </section>
          </template>
          <el-empty v-else description="先找到商品，再选择规格" :image-size="78"/>
        </section>
        <aside class="panel sales-basket" aria-label="本次已选清单" data-sales-basket>
          <div class="section-head"><h2>本次已选</h2><span>{{validation.physicalCount}} 件商品 · {{validation.serviceCount}} 项服务</span></div>
          <p v-if="!draft.goods.length&&!draft.services.length" class="muted empty-basket">查看商品不会自动加入清单。</p>
          <article v-for="row in validation.goods" :key="row.line.id" class="basket-row" :data-sales-position="row.line.id">
            <div class="section-head"><button class="product-link" @click="browseSku(row.line.skuId,row.line.id)">{{row.summary.name}}</button><el-button link type="danger" :disabled="!canEdit||businessPending" :aria-label="`移除 ${row.summary.name}`" @click="removePosition(row.line.id)">移除</el-button></div>
            <p class="muted">{{displaySpec(row.line.skuId,row.summary.spec)}}</p><small v-if="originLabel(row.line.id)">{{originLabel(row.line.id)}}</small>
            <div class="quantity-line"><el-input-number :model-value="row.line.quantity" :min="1" :max="999999" :precision="0" size="small" :disabled="!canEdit||businessPending" :aria-label="`${row.summary.name} 数量`" @change="(value:number|undefined)=>changeQuantity(row.line.id,value)"/><el-tag v-if="row.line.role==='host'" size="small" type="info">手机实物</el-tag></div>
            <p v-for="issue in issuesFor(row.line.id,row.line.skuId)" :key="issue.code+issue.message" class="line-issue">{{issue.message}}</p>
            <details v-for="issue in conditionsFor(row.line.id)" :key="issue.confirmationKey"><summary>核对使用条件</summary><p>{{issue.message}}</p><ul><li v-for="condition in conditionDetail(issue)?.conditions||[]" :key="condition.label">{{condition.label}}</li></ul><el-input v-model="conditionNotes[issue.confirmationKey!]" type="textarea" :rows="2" placeholder="本次如何满足条件" aria-label="本次条件确认说明"/><el-button size="small" @click="confirmCondition(row.line.id,issue)">确认本次条件</el-button></details>
          </article>
          <article v-for="service in draft.services" :key="service.id" class="basket-row" :data-sales-service="service.id"><div class="section-head"><strong>{{service.name}}</strong><el-button link type="danger" :disabled="!canEdit||businessPending" @click="removePosition(service.id)">移除</el-button></div><p class="muted">{{service.description}} {{service.validity}}</p><div class="quantity-line"><el-input-number :model-value="service.quantity" :min="1" :max="999999" :precision="0" size="small" :disabled="!canEdit||businessPending" :aria-label="`${service.name} 数量`" @change="(value:number|undefined)=>changeServiceQuantity(service.id,value)"/><small>{{service.unit}} · {{service.measurement==='per-delivery'?'本次交付':'每份方案'}}</small></div></article>
          <div class="basket-quote"><div class="section-head"><strong>{{formatBenefitCents(draft.quote.amountCents)}}</strong><el-button link @click="quoteOpen=!quoteOpen">{{quoteOpen?'收起报价':'填写报价'}}</el-button></div><div v-if="quoteOpen" class="quote-editor"><el-input v-model="quoteText" inputmode="decimal" placeholder="待报价" aria-label="本次方案报价" @compositionstart="quoteComposing=true" @compositionend="quoteComposing=false" @keydown.enter="commitQuote" @blur="commitQuote" clearable/><el-button :disabled="quoteComposing||!canEdit||businessPending" @click="reviewQuote">核对报价</el-button></div><small v-if="validation.quoteNeedsReview" class="line-issue">清单或依据变化，请重新核对报价。</small></div>
          <div v-if="inputError" class="line-issue" role="alert">{{inputError}}</div>
          <details v-if="otherIssues.length" class="checklist-issues"><summary>还有 {{otherIssues.length}} 项需要处理</summary><p v-for="issue in otherIssues" :key="issue.code+issue.message">{{issue.message}}</p></details>
          <div class="basket-actions"><el-button :disabled="!canPersist||businessPending" @click="saveScheme" data-sales-save>保存方案</el-button><el-button type="primary" :disabled="!canPersist||!store.can('product:delivery:create')||businessPending||!draft.goods.length&&!draft.services.length" :loading="businessPending" @click="checkout" data-sales-checkout>核对交付</el-button></div>
        </aside>
      </div>
    </template>
    <el-dialog v-model="deviceOpen" title="选择使用设备" width="min(580px,94vw)"><p class="muted">用于核对配件适用性，不会加入手机实物。</p><el-radio-group v-model="deviceMode"><el-radio-button value="sku">已有商品</el-radio-button><el-radio-button value="model">设备型号</el-radio-button></el-radio-group><el-select v-if="deviceMode==='sku'" v-model="deviceSkuChoice" filterable placeholder="选择具体手机规格" aria-label="选择使用设备商品"><el-option v-for="sku in deviceSkus" :key="sku.skuId" :value="sku.skuId" :label="`${sku.name} · ${sku.spec}`"/></el-select><DeviceModelPicker v-else v-model="deviceModelChoice" :options="models" label="选择已有设备型号"/><template #footer><el-button @click="deviceOpen=false">取消</el-button><el-button type="primary" :disabled="deviceMode==='sku'?!deviceSkuChoice:!deviceModelChoice" @click="confirmDevice">使用此设备</el-button></template></el-dialog>
    <el-dialog v-model="nameOpen" title="保存销售方案" width="min(520px,94vw)"><el-input v-model="nameText" aria-label="销售方案名称" placeholder="销售方案" maxlength="80"/><template #footer><el-button @click="nameOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="confirmSaveName">保存</el-button></template></el-dialog>
    <el-drawer v-model="recordsOpen" title="销售记录" size="min(620px,95vw)"><p v-if="!savedSchemes.length" class="muted">尚无销售方案。</p><div v-for="record in savedSchemes" :key="record.id" class="record-row"><div><strong>{{record.name}}</strong><p class="muted">{{record.code}} · {{record.goods.length}} 项商品 · {{record.services.length}} 项服务</p></div><el-button @click="openSaved(record)">打开</el-button></div></el-drawer>
    <el-drawer v-model="commonOpen" title="常用组合" size="min(620px,95vw)"><p v-if="!commonSchemes.length" class="muted">可在常用组合中收藏已保存的组合。</p><div v-for="record in commonSchemes" :key="record.id" class="record-row"><div><strong>{{record.name}}</strong><p class="muted">{{record.goods.length}} 项商品 · {{record.services.length}} 项服务</p></div><el-button v-if="record.compositionVersion===2" @click="useCommon(record)">新方案使用</el-button><el-button v-else link @click="router.push(`/benefit-packages/${record.id}`)">查看历史组合</el-button></div></el-drawer>
    <el-dialog v-model="deliveryOpen" title="核对交付清单" width="min(760px,96vw)" :close-on-click-modal="false"><template v-if="preview"><p>{{preview.packageName}} · {{formatBenefitCents(preview.quote.totalCents)}}</p><el-table :data="[...preview.goods.map(row=>({name:row.name,detail:row.spec,quantity:row.totalQuantity})),...preview.services.map(row=>({name:row.name,detail:row.validity,quantity:row.totalQuantity}))]"><el-table-column prop="name" label="商品 / 服务"/><el-table-column prop="detail" label="规格 / 约定"/><el-table-column prop="quantity" label="数量" width="80"/></el-table><p v-for="issue in preview.issues" :key="issue.code+issue.message" class="line-issue">{{issue.message}}</p><el-checkbox v-model="confirmed" :disabled="!preview.canConfirm">已核对商品、数量、适用条件与报价</el-checkbox></template><template #footer><el-button @click="deliveryOpen=false">继续选购</el-button><el-button type="primary" :disabled="!preview?.canConfirm||!confirmed||businessPending" :loading="businessPending" @click="generateDelivery" data-sales-generate>生成交付清单</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter, onBeforeRouteLeave } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageHead from '../components/PageHead.vue'
import CategoryFilterTree from '../components/CategoryFilterTree.vue'
import DeviceModelPicker from '../components/compatibility/DeviceModelPicker.vue'
import { useSalesShoppingDraft } from '../components/sales-shopping/useSalesShoppingDraft'
import { categoryFilterCaption } from '../domain/categoryTree'
import { categoryPath, descendantIds, shelfOf, projectAttrs } from '../domain/logic'
import { isRealSku } from '../domain/catalogIdentity'
import { familyBrandText, familyBrandValues, savedSkuCode, savedSkuSpec } from '../domain/productList'
import { compatibilityRecordRole, listDeviceModels } from '../domain/deviceResolution'
import { addBenefitSku, benefitSkuSummary, cloneBenefit, confirmBenefitCondition, parseBenefitAmount, reviewBenefitQuote, setBenefitDevice, setBenefitPositionQuantity } from '../domain/benefitPackages'
import { querySalesCandidates, addSalesCandidate, attachSalesSource, removeSalesPosition, createSalesCandidateIndex, setSalesDevice } from '../domain/salesSelection'
import type { BenefitDeviceContext, BenefitIssue, BenefitPackageDraft } from '../domain/benefitPackageTypes'
import type { SalesCandidate } from '../domain/salesConfigurationTypes'
import { amountInput, formatBenefitCents } from '../components/benefit-package/benefitPackagePresentation'

const router=useRouter(),route=useRoute()
const session=useSalesShoppingDraft()
const {store,draft,validation,saving,businessPending,error,inputError,missing,canEdit,canPersist,saveState,saveLabel,preview,confirmed,change,clearInputError,retry}=session
const supported=computed(()=>draft.value.compositionVersion===2&&(!draft.value.sales||draft.value.sales.schemaVersion===1))
const keyword=ref(''),brand=ref(''),categoryIds=ref<string[]>([]),shownCount=ref(24),selectedFamilyId=ref(''),sourceSkuId=ref(''),sourcePositionId=ref<string>()
const trail=ref<{skuId:string;positionId?:string}[]>([])
const nameOpen=ref(false),nameText=ref(''),recordsOpen=ref(false),commonOpen=ref(false),deliveryOpen=ref(false),quoteOpen=ref(false),quoteText=ref(''),quoteComposing=ref(false),quoteError=ref('')
const deviceOpen=ref(false),deviceMode=ref<'sku'|'model'>('sku'),deviceSkuChoice=ref(''),deviceModelChoice=ref(''),conditionNotes=ref<Record<string,string>>({})
if(typeof route.query.scheme==='string')session.loadInitial(route.query.scheme)
quoteText.value=amountInput(draft.value.quote.amountCents)
const realSkus=computed(()=>store.data.skus.filter(sku=>isRealSku(store.data,sku)&&sku.status==='on_sale'&&shelfOf(store.data.families.find(family=>family.id===sku.familyId)!)==='online'))
const skuByFamily=computed(()=>{const map=new Map<string,typeof realSkus.value>();for(const sku of realSkus.value){const rows=map.get(sku.familyId)||[];rows.push(sku);map.set(sku.familyId,rows)}return map})
const familySkus=(id:string)=>skuByFamily.value.get(id)||[]
const attributeLabels=computed(()=>new Map(store.data.params.map(param=>[param.id,param.name])))
function displaySpec(id:string,fallback=''){const sku=store.data.skus.find(item=>item.id===id),family=sku&&store.data.families.find(item=>item.id===sku.familyId);return sku&&family?Object.entries(projectAttrs(family,sku)).filter(([,value])=>value.trim()).map(([key,value])=>`${attributeLabels.value.get(key)||key} ${value}`).join(' · ')||fallback:fallback}
const brands=computed(()=>[...new Set(store.data.families.flatMap(family=>familyBrandValues(store.data,family)))].sort((a,b)=>a.localeCompare(b,'zh')))
const categoryCaption=computed(()=>categoryFilterCaption(store.data.categories,categoryIds.value,true))
const families=computed(()=>{const ids=new Set(categoryIds.value.flatMap(id=>descendantIds(store.data.categories,id))),term=keyword.value.trim().toLocaleLowerCase();return store.data.families.filter(family=>{const skus=familySkus(family.id);return skus.length&&(!ids.size||ids.has(family.categoryId))&&(!brand.value||familyBrandValues(store.data,family).includes(brand.value))&&(!term||`${family.name} ${skus.map(sku=>`${savedSkuCode(sku)} ${savedSkuSpec(family,sku)} ${sku.skuName||''}`).join(' ')}`.toLocaleLowerCase().includes(term))})})
const shownFamilies=computed(()=>families.value.slice(0,shownCount.value)),selectedFamily=computed(()=>store.data.families.find(family=>family.id===selectedFamilyId.value))
watch([keyword,brand,categoryIds],()=>{shownCount.value=24})
const sourceSummary=computed(()=>benefitSkuSummary(store.data,sourceSkuId.value)),sourceRole=computed(()=>compatibilityRecordRole(store.data,sourceSkuId.value))
const candidateIndex=computed(()=>createSalesCandidateIndex(store.data))
const candidates=computed(()=>querySalesCandidates(store.data,draft.value,sourceSkuId.value,candidateIndex.value,sourcePositionId.value||undefined))
const candidateGroups=computed(()=>{const groups=new Map<string,{key:string;name:string;required:boolean;rows:SalesCandidate[]}>();for(const row of candidates.value.rows){const key=`${row.plan?.planId||'related'}:${row.item.id}`;if(!groups.has(key))groups.set(key,{key,name:row.item.name,required:row.item.required,rows:[]});groups.get(key)!.rows.push(row)}return [...groups.values()]})
const models=computed(()=>listDeviceModels(store.data))
const deviceSkus=computed(()=>realSkus.value.filter(sku=>compatibilityRecordRole(store.data,sku.id)==='host').map(sku=>benefitSkuSummary(store.data,sku.id)!))
const deviceLabel=computed(()=>draft.value.device?.kind==='sku'?benefitSkuSummary(store.data,draft.value.device.skuId)?.name||'设备已失效':draft.value.device?.kind==='model'?models.value.find(model=>JSON.stringify(model.host)===JSON.stringify(draft.value.device?.kind==='model'?draft.value.device.host:null))?.label||draft.value.device.host.steps.map(step=>step.valueId).join(' · '):'尚未指定')
const savedSchemes=computed(()=>(store.can('product:benefit:read')?store.data.benefitPackages||[]:[]).filter(record=>record.sales).slice().sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)))
const commonSchemes=computed(()=>(store.can('product:benefit:read')?store.data.benefitPackages||[]:[]).filter(record=>record.favorite&&record.status!=='disabled'))
const otherIssues=computed(()=>validation.value.issues.filter(issue=>!issue.positionId&&!issue.skuId&&issue.code!=='quote-review'))
function toggleCategory(id:string,multiple=false){categoryIds.value=multiple?(categoryIds.value.includes(id)?categoryIds.value.filter(value=>value!==id):[...categoryIds.value,id]):[id]}
function openFamily(id:string){selectedFamilyId.value=id;const skus=familySkus(id);if(skus.length===1)browseSku(skus[0]!.id);else if(!skus.some(sku=>sku.id===sourceSkuId.value)){sourceSkuId.value='';sourcePositionId.value=undefined;trail.value=[]}}
function browseSku(id:string,positionId?:string){const sku=store.data.skus.find(item=>item.id===id);if(!sku)return;if(positionId&&!draft.value.goods.some(line=>line.id===positionId&&line.skuId===id))positionId=undefined;selectedFamilyId.value=sku.familyId;sourceSkuId.value=id;sourcePositionId.value=positionId;const previous=trail.value.findIndex(item=>item.skuId===id&&item.positionId===positionId);trail.value=previous>=0?trail.value.slice(0,previous+1):[...trail.value,{skuId:id,positionId}].slice(-16)}
function returnToSource(index:number){const entry=trail.value[index];if(entry)browseSku(entry.skuId,entry.positionId)}
function apply(operation:(value:BenefitPackageDraft)=>BenefitPackageDraft){clearInputError();const accepted=change(operation);if(quoteError.value)inputError.value=quoteError.value;return accepted}
function chooseDevice(device:BenefitDeviceContext){if(apply(value=>setSalesDevice(store.data,value,device)))deviceOpen.value=false}
function confirmDevice(){if(deviceMode.value==='sku')chooseDevice({kind:'sku',skuId:deviceSkuChoice.value});else{const model=models.value.find(item=>item.key===deviceModelChoice.value);if(model)chooseDevice({kind:'model',host:cloneBenefit(model.host)})}}
function addCurrent(){const id=sourceSkuId.value;if(!id)return;const accepted=apply(value=>{let next=value;if(sourceRole.value==='host'&&!next.device)next=setBenefitDevice(store.data,next,{kind:'sku',skuId:id});next=addBenefitSku(store.data,next,id,1,{role:sourceRole.value==='host'?'host':'item',groupId:null});const line=next.goods.find(item=>item.skuId===id&&item.groupId===null&&item.role===(sourceRole.value==='host'?'host':'item'));return attachSalesSource(store.data,next,id,line?.id)});if(accepted){const line=draft.value.goods.find(item=>item.skuId===id&&item.groupId===null&&item.role===(sourceRole.value==='host'?'host':'item'));if(line)browseSku(id,line.id)}}
function addCandidate(candidate:SalesCandidate){const oldIds=new Set(draft.value.goods.map(line=>line.id));if(!apply(value=>addSalesCandidate(store.data,value,candidate,{sourcePositionId:sourcePositionId.value})))return;if(candidate.skuId){const added=draft.value.goods.find(line=>!oldIds.has(line.id)&&line.skuId===candidate.skuId);const origin=draft.value.sales?.origins.find(item=>item.sourceSkuId===candidate.sourceSkuId&&item.itemId===candidate.item.id&&item.plan?.planId===candidate.plan?.planId&&item.plan?.version===candidate.plan?.version&&item.sourcePositionId===sourcePositionId.value);const next=querySalesCandidates(store.data,draft.value,candidate.skuId,candidateIndex.value);if(next.rows.length)browseSku(candidate.skuId,added?.id||origin?.positionId)}}
function removePosition(id:string){if(apply(value=>removeSalesPosition(value,id))){if(sourcePositionId.value===id)sourcePositionId.value=undefined;for(const key of Object.keys(conditionNotes.value))if(key.includes(id))delete conditionNotes.value[key]}}
function changeQuantity(id:string,value:number|undefined){if(value!==undefined)apply(current=>setBenefitPositionQuantity(store.data,current,id,value))}
function changeServiceQuantity(id:string,value:number|undefined){if(value===undefined)return;apply(current=>{const service=current.services.find(item=>item.id===id);if(!service||!Number.isSafeInteger(value)||value<1)throw Error('服务数量须为正整数。');service.quantity=value;current.confirmations=[];return current})}
function originLabel(id:string){const origin=draft.value.sales?.origins.find(item=>item.positionId===id);if(!origin)return '';return `${origin.plan?.items.find(item=>item.id===origin.itemId)?.name||'相关商品'} · 来自 ${benefitSkuSummary(store.data,origin.sourceSkuId)?.name||'来源已失效'}`}
function issuesFor(id:string,skuId:string){return validation.value.issues.filter(issue=>issue.severity!=='warning'&&issue.code!=='condition-confirmation'&&(issue.positionId===id||!issue.positionId&&issue.skuId===skuId))}
function conditionsFor(id:string){return validation.value.issues.filter(issue=>issue.code==='condition-confirmation'&&issue.positionId===id)}
function conditionDetail(issue:BenefitIssue){const row=validation.value.goods.find(item=>item.line.id===issue.positionId);return row?.compatibility.capabilities.find(detail=>JSON.stringify([row.line.id,row.line.skuId,detail.capability])===issue.confirmationKey)}
function confirmCondition(id:string,issue:BenefitIssue){const capability=conditionDetail(issue)?.capability;if(capability==='basic'||capability==='fast-charge')apply(value=>confirmBenefitCondition(store.data,value,id,conditionNotes.value[issue.confirmationKey!]||'',new Date().toISOString(),capability))}
function statusType(status:SalesCandidate['status']){return status==='compatible'?'success':status==='incompatible'?'danger':status==='conditional'||status==='pending'?'warning':'info'}
function statusLabel(candidate:SalesCandidate){return {compatible:'已确认适用',conditional:'需核对条件',pending:'依据待确认',incompatible:'明确不适用','not-required':'搭配推荐'}[candidate.status]}
function targetLabel(candidate:SalesCandidate){return candidate.item.checkTarget==='source'?'核对当前来源商品':candidate.item.checkTarget==='device'?'核对本次使用设备':'不作适用承诺'}
function commitQuote(event?:Event){if(quoteComposing.value||event instanceof KeyboardEvent&&(event.isComposing||event.keyCode===229))return false;try{const amount=parseBenefitAmount(quoteText.value);quoteError.value='';clearInputError();if(amount===draft.value.quote.amountCents)return true;return apply(value=>{value.quote.amountCents=amount;value.quote.reviewedBasis='';return value})}catch(cause){quoteError.value=cause instanceof Error?cause.message:String(cause);inputError.value=quoteError.value;return false}}
function reviewQuote(){if(commitQuote())apply(value=>reviewBenefitQuote(value,store.data))}
function saveScheme(){if(!commitQuote())return;nameText.value=draft.value.name||'销售方案';nameOpen.value=true}
async function confirmSaveName(){if(!nameText.value.trim()){inputError.value='请填写方案名称。';return}if(!apply(value=>({...value,name:nameText.value.trim()})))return;if(await session.flush()){nameOpen.value=false;ElMessage.success('销售方案已保存')}}
async function changeSession(source?:BenefitPackageDraft,copy=false){if(await session.replaceSession(source,copy))return true;if(businessPending.value)return false;try{await ElMessageBox.confirm('最新输入尚未保存，切换将放弃本页这些修改。','切换销售方案',{confirmButtonText:'放弃修改并切换',cancelButtonText:'继续处理',type:'warning'});return session.replaceSession(source,copy,true)}catch{return false}}
async function newSession(){if(await changeSession()){sourceSkuId.value='';sourcePositionId.value=undefined;selectedFamilyId.value='';trail.value=[];quoteText.value='';quoteError.value='';conditionNotes.value={}}}
async function openSaved(record:BenefitPackageDraft){if(await changeSession(record)){recordsOpen.value=false;quoteText.value=amountInput(record.quote.amountCents);quoteError.value='';sourceSkuId.value='';sourcePositionId.value=undefined;trail.value=[]}}
async function useCommon(record:BenefitPackageDraft){if(await changeSession({...cloneBenefit(record),sales:record.sales||{schemaVersion:1,origins:[],contexts:[]}},true)){commonOpen.value=false;quoteText.value=amountInput(record.quote.amountCents);quoteError.value='';sourceSkuId.value='';sourcePositionId.value=undefined;trail.value=[]}}
async function checkout(){if(!commitQuote())return;if(await session.prepareDelivery())deliveryOpen.value=true}
async function generateDelivery(){const result=await session.generate();if(result.ok&&result.delivery)await router.push(`/benefit-packages/deliveries/${result.delivery.id}`)}
watch([()=>store.activeUserId,()=>store.previewUserId],()=>{quoteText.value=amountInput(draft.value.quote.amountCents);quoteError.value='';conditionNotes.value={};deliveryOpen.value=false;nameOpen.value=false;deviceOpen.value=false;recordsOpen.value=false;commonOpen.value=false;sourcePositionId.value=undefined})
onBeforeRouteLeave(async()=>{if(businessPending.value)return false;if(commitQuote()&&await session.flush())return true;try{await ElMessageBox.confirm('最新输入尚未保存。离开将放弃本页未保存的修改。','离开销售选购',{confirmButtonText:'放弃并离开',cancelButtonText:'继续处理',type:'warning'});return true}catch{return false}})
</script>

